// COALESCE on the non-nullable name; the four timer columns + the
// description column are nullable so use the (set, value) CASE
// pattern to distinguish "clear to NULL" from "key omitted".
// options_json gets the same set/value split — Python's PATCH treats
// {"options": null} as "clear to empty array" and missing key as
// "keep current"; the API handler resolves that to options_set with
// value [] vs options_set=false. ip_family + fabric_id are immutable
// (Python doesn't expose them in the PATCH model).
func (q *Queries) UpdateDhcpScopeTemplate(ctx context.Context, arg UpdateDhcpScopeTemplateParams) (DhcpScopeTemplate, error) {
	row := q.db.QueryRow(ctx, updateDhcpScopeTemplate,
		arg.ID,
		arg.Name,
		arg.OptionsSet,
		arg.OptionsJSON,
		arg.ValidLifetimeSet,
		arg.ValidLifetimeSeconds,
		arg.RenewTimerSet,
		arg.RenewTimerSeconds,
		arg.RebindTimerSet,
		arg.RebindTimerSeconds,
		arg.PreferredLifetimeSet,
		arg.PreferredLifetimeSeconds,
		arg.DescriptionSet,
		arg.Description,
	)
	var i DhcpScopeTemplate
	err := row.Scan(
		&i.ID,
		&i.FabricID,
		&i.Name,
		&i.IPFamily,
		&i.OptionsJSON,
		&i.ValidLifetimeSeconds,
		&i.RenewTimerSeconds,
		&i.RebindTimerSeconds,
		&i.PreferredLifetimeSeconds,
		&i.Description,
		&i.CreatedAt,
		&i.UpdatedAt,
	)
	return i, err
}

